CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE IF NOT EXISTS "user" (id text PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, email_verified boolean NOT NULL DEFAULT false, image text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS session (id text PRIMARY KEY, user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, token text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, ip_address text, user_agent text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS session_user_idx ON session(user_id);
CREATE TABLE IF NOT EXISTS account (id text PRIMARY KEY, user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, account_id text NOT NULL, provider_id text NOT NULL, access_token text, refresh_token text, id_token text, access_token_expires_at timestamptz, refresh_token_expires_at timestamptz, scope text, password text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS verification (id text PRIMARY KEY, identifier text NOT NULL, value text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name) BETWEEN 2 AND 80), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS organization_members (organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('admin','member')), PRIMARY KEY(organization_id,user_id));
CREATE TABLE IF NOT EXISTS teams (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name text NOT NULL CHECK(length(name) BETWEEN 2 AND 80), description text NOT NULL DEFAULT '', UNIQUE(id,organization_id));
CREATE TABLE IF NOT EXISTS team_members (organization_id uuid NOT NULL, team_id uuid NOT NULL, user_id text NOT NULL, role text NOT NULL CHECK(role IN ('manager','member')), PRIMARY KEY(team_id,user_id), FOREIGN KEY(team_id,organization_id) REFERENCES teams(id,organization_id) ON DELETE CASCADE, FOREIGN KEY(organization_id,user_id) REFERENCES organization_members(organization_id,user_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS invitations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, team_id uuid NOT NULL, email text NOT NULL, role text NOT NULL CHECK(role IN ('manager','member')), token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, accepted_at timestamptz, FOREIGN KEY(team_id,organization_id) REFERENCES teams(id,organization_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), actor_id text NOT NULL REFERENCES "user"(id), action text NOT NULL, target_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, team_id uuid NOT NULL, title text NOT NULL, object_key text NOT NULL UNIQUE, format text NOT NULL CHECK(format IN ('pdf','docx','txt')), size integer NOT NULL CHECK(size > 0 AND size <= 20971520), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','processing','ready','failed','deleted')), error text, created_by text NOT NULL REFERENCES "user"(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,team_id,organization_id), FOREIGN KEY(team_id,organization_id) REFERENCES teams(id,organization_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS chunks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_id uuid NOT NULL REFERENCES documents(id) ON DELETE CASCADE, location text NOT NULL, content text NOT NULL, embedding vector(1536));
CREATE INDEX IF NOT EXISTS chunks_document_idx ON chunks(document_id);
CREATE TABLE IF NOT EXISTS jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_id uuid NOT NULL REFERENCES documents(id) ON DELETE CASCADE, kind text NOT NULL DEFAULT 'ingest' CHECK(kind IN ('ingest','delete')), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','processing','done','failed')), attempts integer NOT NULL DEFAULT 0, lease_until timestamptz, claim_id uuid, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, team_id uuid NOT NULL, author_id text NOT NULL REFERENCES "user"(id), title text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,team_id,organization_id), FOREIGN KEY(team_id,organization_id) REFERENCES teams(id,organization_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS messages (sequence bigserial UNIQUE, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('user','assistant')), content text NOT NULL, source_ids jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS guided_steps (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, instruction text NOT NULL, result text CHECK(result IN ('worked','failed','unable')), created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS one_pending_step ON guided_steps(conversation_id) WHERE result IS NULL;
CREATE TABLE IF NOT EXISTS requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, team_id uuid NOT NULL, author_id text NOT NULL REFERENCES "user"(id), title text NOT NULL, summary text NOT NULL, status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_progress','resolved','closed')), assignee_id text REFERENCES "user"(id), confirmation_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(author_id,confirmation_id), UNIQUE(id,team_id,organization_id), FOREIGN KEY(team_id,organization_id) REFERENCES teams(id,organization_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS request_comments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES requests(id) ON DELETE CASCADE, author_id text NOT NULL REFERENCES "user"(id), content text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS generation_limits (user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, window_start timestamptz NOT NULL, count integer NOT NULL, PRIMARY KEY(user_id,window_start));
CREATE INDEX IF NOT EXISTS document_scope_idx ON documents(team_id,organization_id);
CREATE INDEX IF NOT EXISTS conversation_author_idx ON conversations(author_id,team_id);
CREATE INDEX IF NOT EXISTS requests_scope_idx ON requests(team_id,organization_id);
